const item = $input.item.json;

const bn = item.preferred_lang === 'bn';

const message = bn
  ? `প্রিয় ${item.manager_id ?? 'ম্যানেজার'},\n\n` +
    `এই বার্তাটি জরুরি ভিত্তিতে আপনার দৃষ্টি আকর্ষণের জন্য পাঠানো হচ্ছে।\n\n` +
    `নতুন কর্মী ${item.full_name}-এর অনবোর্ডিং কাজ "${item.task_name}" ` +
    `${item.days_overdue} দিন ধরে অসম্পন্ন রয়েছে (দায়িত্বপ্রাপ্ত: ${item.owner})। ` +
    `অনুগ্রহ করে অবিলম্বে প্রয়োজনীয় ব্যবস্থা গ্রহণ করুন।\n\n` +
    `ধন্যবাদ,\nHR অনবোর্ডিং টিম`
  : `Dear ${item.manager_id ?? 'Manager'},\n\n` +
    `This is an urgent escalation regarding a pending onboarding task.\n\n` +
    `The task "${item.task_name}" for new hire ${item.full_name} is now ` +
    `${item.days_overdue} day(s) overdue (assigned to: ${item.owner}). ` +
    `Immediate action is required.\n\n` +
    `Regards,\nHR Onboarding Team`;

return {
  ...item,
  draft_message: message
};

const item = $input.item.json;

const bn = item.preferred_lang === 'bn';

const message = bn
  ? `প্রিয় ${item.owner},\n\n` +
    `অনুগ্রহ করে মনে করিয়ে দেওয়া হচ্ছে যে নতুন কর্মী ${item.full_name}-এর ` +
    `অনবোর্ডিং কাজ "${item.task_name}" ${item.days_overdue} দিন ধরে অসম্পন্ন রয়েছে। ` +
    `দয়া করে যত দ্রুত সম্ভব এটি সম্পন্ন করুন।\n\n` +
    `ধন্যবাদ,\nHR অনবোর্ডিং টিম`
  : `Dear ${item.owner},\n\n` +
    `This is a friendly reminder that the onboarding task "${item.task_name}" ` +
    `for new hire ${item.full_name} is ${item.days_overdue} day(s) overdue. ` +
    `Please complete it at your earliest convenience.\n\n` +
    `Regards,\nHR Onboarding Team`;

return {
  ...item,
  draft_message: message
};
